pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));

        // Call assertionDisputedCallback as the optimistic asserter (address(this))
        c.assertionDisputedCallback(bytes32(0));

        // Now attempt to call requestPrice as the fuzzed caller
        bytes32 identifier = bytes32(0);
        uint256 time = 0;
        bytes memory ancillaryData = "";
        bool success;
        vm.prank(caller);
        try c.requestPrice(identifier, time, ancillaryData) {
            success = true;
        } catch {
            success = false;
        }

        // Rule: after assertionDisputedCallback, requestPrice must revert when called by a non-optimistic asserter.
        // Reference C reverts (success == false), buggy M succeeds (success == true).
        assertFalse(success);
    }
}

